180		/// @todo exit with errors if any of the above failed?
181	
182		if ($Rows == 0) { /* Then the database does not exist */
183			//if ($Privileges == 0) {
184			//	$Errors[] = __('The database does not exist, and this database user does not have privileges to create it');
185			//} else { /* Then we can create the database */
186				$SQL = "CREATE DATABASE " . $DataBaseName . " CHARACTER SET = " . $_SESSION['Installer']['DBCharset'];
187				if (!@mysqli_query($DB, $SQL)) {
188					$Errors[] = __('Failed creating the database');
189				}
190			//}
191		} else {
192	
193			/* Need to make sure NO data is removed from the existing DB */
194	
195			$SQL = "SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA = '" . $DataBaseName . "'";
196			if (!($Result = @mysqli_query($DB, $SQL))) {
197				$Errors[] = __('Failed enumerating existing database tables');
198			} else {
199				// only check tables which we will recreate
200				$Rows = @mysqli_fetch_all($Result, MYSQLI_ASSOC);
201				$ExistingTablesNum = count($Rows);
202				$TableNames = array();
203				foreach (glob($Path_To_Root . '/install/sql/tables/*.sql') as $FileName) {
204					$SQLScriptFile = file_get_contents($FileName);
205					if (preg_match('/^CREATE +TABLE +`?([^ (`]+)`?/', $SQLScriptFile, $matches)) {
206						$TableNames[] = str_replace('`', '', $matches[1]);
207					}
208				}
209				foreach($Rows as $i => $Row) {
210					if (!in_array($Row['TABLE_NAME'], $TableNames)) {
211						unset($Rows[$i]);
212					}
213				}
214				if (count($Rows)) {
215					$Errors[] = __('Would overwrite' . ' ' . count($Rows) . ' ' . 'existing database tables');
216				} else {
217					if ($ExistingTablesNum > 0) {
218						echo '<div class="warning">' . __('Found') . ' ' . $ExistingTablesNum . ' ' . __('unrelated tables in the existing schema') . '</div>';
219					}
220				}
221			}
222		}
223	
224		if ($Errors) {
225			echo '<div class="error">' . __('Unable to create the database schema.') . '</div>';
226	
227			// display the errors
228			echo '<div class="error">';
229			foreach ($Errors as $error) {
230				echo '<p>' . htmlspecialchars($error) . "</p>\n";
231			}
232			echo '</div>';
233	
234			return false;
235		}
236	
237		return true;
238	}
