240	function CreateCompanyFolder($DatabaseName, $Path_To_Root) {
241		$CompanyDir = $Path_To_Root . '/companies/' . $DatabaseName;
242	
243		if (is_file($CompanyDir)) {
244			echo '<div class="error">' . __('The company config directory can not be created as a file exists at its place') . '</div>';
245			return false;
246		}
247	
248		if (is_dir($CompanyDir)) {
249			/// @todo allow more flexibility? Check if $database.bak does not exist, rename the current dir and go on
250			$files = glob($CompanyDir . '/*');
251			if (count($files)) {
252				echo '<div class="error">' . __('The company config directory exists and is not empty') . '</div>';
253				flush();
254				return false;
255			}
256			$Result = true;
257		} else {
258			$Result = mkdir($CompanyDir);
259		}
260	
261		if ($Result) {
262			$Result = $Result && mkdir($CompanyDir . '/part_pics');
263			$Result = $Result && mkdir($CompanyDir . '/EDI_Incoming_Orders');
264			$Result = $Result && mkdir($CompanyDir . '/reports');
265			$Result = $Result && mkdir($CompanyDir . '/EDI_Sent');
266			$Result = $Result && mkdir($CompanyDir . '/EDI_Pending');
267			$Result = $Result && mkdir($CompanyDir . '/reportwriter');
268			$Result = $Result && mkdir($CompanyDir . '/pdf_append');
269			$Result = $Result && mkdir($CompanyDir . '/FormDesigns');
270	
271			$Result = $Result && copy($Path_To_Root . '/companies/weberpdemo/FormDesigns/GoodsReceived.xml', $CompanyDir . '/FormDesigns/GoodsReceived.xml');
272			$Result = $Result && copy($Path_To_Root . '/companies/weberpdemo/FormDesigns/PickingList.xml', $CompanyDir . '/FormDesigns/PickingList.xml');
273			$Result = $Result && copy($Path_To_Root . '/companies/weberpdemo/FormDesigns/PurchaseOrder.xml', $CompanyDir . '/FormDesigns/PurchaseOrder.xml');
274			$Result = $Result && copy($Path_To_Root . '/companies/weberpdemo/FormDesigns/Journal.xml', $CompanyDir . '/FormDesigns/Journal.xml');
275		}
276	
277		if ($Result) {
278			echo '<div class="success">' . __('The company config directory has been successfully created') . '</div>';
279		} else {
280			echo '<div class="error">' . __('The company config directory was not created successfully') . '</div>';
281		}
282		flush();
283	
284		// failure to save the logo is not fatal for the installer
285		if (is_dir($CompanyDir)) {
286			if (isset($_FILES["LogoFile"]) && $_FILES["LogoFile"]["tmp_name"] != '') {
287				SaveUploadedCompanyLogo($DatabaseName, $Path_To_Root);
288			} else {
289				CreateCompanyLogo($DatabaseName, $Path_To_Root, $CompanyDir);
290			}
291		}
292	
293		return $Result;
294	}
