296	/**
297	 * @param $Path_To_Root
298	 * @return bool
299	 */
300	function CreateTables($Path_To_Root, $DBType) {
301		$DBErrors = 0;
302		foreach (glob($Path_To_Root . '/install/sql/tables/*.sql') as $FileName) {
303			$SQLScriptFile = file_get_contents($FileName);
304	
305			if ($DBType == 'mariadb') {
306				// mariadb 5.5 chokes on STORED
307				$SQLScriptFile = preg_replace('/([) ])STORED([, \n])/', ' $1PERSISTENT$2', $SQLScriptFile);
